@dataclass
class ParsedFrontmatter:
    prefix: str
    body: str
    sections: list[tuple[str | None, list[str]]]


def strip_quotes(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in {'"', "'"}:
        return value[1:-1]
    return value


def strip_accents(value: str) -> str:
    normalized = unicodedata.normalize("NFKD", value)
    return "".join(ch for ch in normalized if not unicodedata.combining(ch))


def normalize_tag_value(value: str) -> str | None:
    raw = strip_quotes(value).strip()
    while raw.startswith("#"):
        raw = raw[1:]
    raw = strip_accents(raw).lower().strip()
    if not raw:
        return None

    parts: list[str] = []
    for segment in raw.split("/"):
        segment = segment.strip()
        if not segment:
            continue
        segment = re.sub(r"[\s\-]+", "_", segment)
        segment = re.sub(r"[^a-z0-9_]", "", segment)
        segment = re.sub(r"_+", "_", segment).strip("_")
        if segment:
            parts.append(segment)
    normalized = "/".join(parts)
    return normalized or None


def normalize_alias_value(value: str) -> str:
    return strip_quotes(value).strip()


def split_frontmatter(text: str) -> ParsedFrontmatter | None:
    if not text.startswith("---\n"):
        return None
    closing = text.find("\n---\n", 4)
    if closing == -1:
        return None

    fm_block = text[4:closing]
    body = text[closing + len("\n---\n") :]
    lines = fm_block.splitlines()
    sections: list[tuple[str | None, list[str]]] = []
    current_key: str | None = None
    current_lines: list[str] = []

    def flush() -> None:
        nonlocal current_key, current_lines
        if current_lines:
            sections.append((current_key, current_lines))
        current_key = None
        current_lines = []

    for line in lines:
        if line and not line[0].isspace() and ":" in line:
            flush()
            key = line.split(":", 1)[0].strip()
            current_key = key
            current_lines = [line]
        else:
            if not current_lines:
                sections.append((None, [line]))
            else:
                current_lines.append(line)

    flush()
    return ParsedFrontmatter(prefix=text[:4], body=body, sections=sections)


def parse_items(section_lines: list[str]) -> tuple[str, list[str]]:
    header = section_lines[0]
    key, raw_value = header.split(":", 1)
    values: list[str] = []

    inline = raw_value.strip()
    if inline:
        if inline.startswith("[") and inline.endswith("]"):
            inner = inline[1:-1].strip()
            if inner:
                for item in inner.split(","):
                    cleaned = strip_quotes(item.strip())
                    if cleaned:
                        values.append(cleaned)
        else:
            cleaned = strip_quotes(inline)
            if cleaned:
                values.append(cleaned)
    else:
        for line in section_lines[1:]:
            stripped = line.strip()
            if not stripped or not stripped.startswith("- "):
                continue
            cleaned = strip_quotes(stripped[2:].strip())
            if cleaned:
                values.append(cleaned)

    return key.strip(), values


def collect_note_data(section_lines: list[tuple[str | None, list[str]]]) -> tuple[list[str], list[str], list[str], list[tuple[str | None, list[str]]], list[str]]:
    tags: list[str] = []
    aliases: list[str] = []
    other_sections: list[tuple[str | None, list[str]]] = []
    emitted: list[str] = []
    seen_tags: set[str] = set()
    seen_aliases: set[str] = set()

    for key, lines in section_lines:
        if key is None:
            other_sections.append((key, lines))
            continue

        normalized_key = key.lower()
        if normalized_key in {"tag", "tags"}:
            _, values = parse_items(lines)
            for value in values:
                normalized = normalize_tag_value(value)
                if normalized and normalized not in seen_tags:
                    tags.append(normalized)
                    seen_tags.add(normalized)
            continue

        if normalized_key in {"alias", "aliases"}:
            _, values = parse_items(lines)
            for value in values:
                normalized = normalize_alias_value(value)
                if normalized and normalized not in seen_aliases:
                    aliases.append(normalized)
                    seen_aliases.add(normalized)
            continue

        other_sections.append((key, lines))

    return tags, aliases, emitted, other_sections, []


def frontmatter_key_flags(section_lines: list[tuple[str | None, list[str]]]) -> tuple[bool, bool]:
    has_singular_tag = False
    has_singular_alias = False
    for key, _ in section_lines:
        if key is None:
            continue
        lower = key.lower()
        if lower == "tag":
            has_singular_tag = True
        elif lower == "alias":
            has_singular_alias = True
    return has_singular_tag, has_singular_alias


def render_list_section(key: str, values: list[str]) -> list[str]:
    if not values:
        return []
    lines = [f"{key}:"]
    lines.extend(f"  - {escape_yaml_scalar(value)}" for value in values)
